{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur la confirmation par la juridiction cantonale du refus de renouveler les autorisations de séjour de la personne assurée et de son époux.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Pour se voir reconnaître la qualité de travailleur au sens de l'art. 6 Annexe I ALCP, la personne doit fournir une prestation de travail pendant une certaine durée contre rémunération, sans qu'il importe du temps ou du montant de l'activité.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le droit de séjour dérivé de l'époux ressortissant d'un État tiers dépend de celui de l'épouse ressortissante de l'UE, qui s'éteint avec le refus de l'autorisation de celle-ci.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le temps d'activité ou le montant du salaire ne constituent pas des critères déterminants pour l'acquisition de la qualité de travailleur.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Les parties contractantes peuvent exiger le renouvellement de l'autorisation de séjour après les deux premières années de séjour.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La personne assurée n'a pas acquis la qualité de travailleuse au sens de l'art. 6 Annexe I ALCP, car son emploi auprès de la C.________ GmbH n'a duré que deux jours au maximum et aucune rémunération n'a été démontrée.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le refus de renouveler l'autorisation de séjour de la personne assurée ne viole pas l'art. 6 Annexe I ALCP, de sorte que l'époux ne dispose plus d'un droit dérivé.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "La juridiction cantonale a retenu à juste titre qu'aucun droit conventionnel à un séjour sans activité lucrative ne peut être invoqué par la personne assurée.",
      "b_propositions": ["P8"]
    }
  ]
}
